# scripts/banner.ps1 -- the PowerShell port of scripts/banner.sh.
# The truecolour TensorFold ribbon (tf.png, generated by make_banner.py) with MIA AI LAB.
# The art comes from banner.sh verbatim; <ESC> stands for the ANSI escape byte, kept
# out of this file so it stays editable. UTF-8 with BOM for Windows PowerShell 5.1.
# Like banner(), Show-Banner prints nothing when stdout is redirected or the terminal
# is narrower than 86 columns; the wide ribbon needs 108.

function Show-Banner {
  if ([Console]::IsOutputRedirected) { return }
  $cols = 120
  try {
    $width = $Host.UI.RawUI.WindowSize.Width
    if ($width -gt 0) { $cols = $width }
  } catch { }
  if ($cols -ge 108) { $art = $script:BannerWide }
  elseif ($cols -ge 86) { $art = $script:BannerNarrow }
  else { return }
  $esc = [string][char]27
  foreach ($line in ($art -split "`n")) {
    Write-Host ($line.TrimEnd("`r").Replace('<ESC>', $esc))
  }
}

